```java
// RIGHT: mappedBy points at the 'order' field that owns the FK
@Entity
class Order {
    @Id @GeneratedValue private Long id;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL)
    private List<OrderItem> items = new ArrayList<>();
}

@Entity
class OrderItem {
    @Id @GeneratedValue private Long id;

    @ManyToOne
    @JoinColumn(name = "order_id") // single owning FK
    private Order order;
}
// One foreign key, no duplicate table.
